var fontFamily = "NotoSans";

function retrieveJobOpeningPage(){
	var frm = document.mainFrm;
	frm.action = "/applicantMain/goJobOpeningPage.do";
	frm.submit();
}

function retrieveJobOpeningDetailPage(){
	var frm = document.mainFrm;
	frm.action = "/applicantMain/goJobOpeningDetailPage.do";
	frm.submit();
}
$(document).ready(function(){
	changeFont();
	
	//채용형태별 조회
	$(".category").click(function(){
		$("#openType").val($(this).attr("openType"));
		retrieveJobOpeningPage();
	});
	
	$(".rowArea").click(function(){
		$("#opnIdx").val($(this).attr("opnIdx"));
		retrieveJobOpeningDetailPage();
	});
});

function submitProcess(){
	 var schema = "https";
	 var serverName = "uljuculture.hubst.co.kr";
	 if(serverName == "hubsss.co.kr" || serverName == "hubst.com"){
		 serverName = serverName + ":8080";
	 }
	location.href=schema+"://"+serverName+"/applicantMain/goMainPage.do";	
}



$(function(){
	submitProcess();	
});

var fontFamily = "NotoSans";

function retrieveNoticeDetailPage(){		
	var frm = document.mainFrm
	frm.action = "/applicantMain/goNoticePageDetail.do";
	frm.submit();		
}

function retrieveNoticePage(){		
	var frm = document.mainFrm
	frm.action = "/applicantMain/goNoticePage.do";
	frm.submit();		
}

$(document).ready(function(){
	changeFont();
		
	$(".rowArea").click(function(){		
		$("#postIdx").val($(this).attr("postIdx"));
		retrieveNoticeDetailPage();
	});
	
	$("#opnIdx").change(function(){
		retrieveNoticePage();
	});
	
	if($(".txtAlignCenter").length){
		$("#contentArea").attr("class","hasSubImg");
	}else{
		$("#contentArea").attr("class","noSubImg");
	}
});

